let mt_deck=[],mt_round=0,mt_cycle=0,mt_score=0,mt_streak=0,mt_best=0,mt_locked=false,mt_current=null,mt_tokens=0;
const mt_qState={};
function mt_shuffle(arr){const a=arr.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function mt_buildDeck(){mt_deck=mt_shuffle(MT_SCENES);mt_cycle++;if(mt_current&&mt_deck.length>1&&mt_deck[0].id===mt_current.scene.id){[mt_deck[0],mt_deck[1]]=[mt_deck[1],mt_deck[0]];}}
function mt_pickQ(scene){let st=mt_qState[scene.id];if(!st)st=mt_qState[scene.id]={deck:[],last:-1};if(!st.deck.length){st.deck=mt_shuffle(scene.qs.map((_,i)=>i));if(st.deck.length>1&&st.deck[0]===st.last)[st.deck[0],st.deck[1]]=[st.deck[1],st.deck[0]];}const idx=st.deck.shift();st.last=idx;return scene.qs[idx];}
function mt_next(){if(typeof isMiniGameActive==='function'&&!isMiniGameActive('mall-talk'))return;if(!mt_deck.length)mt_buildDeck();const scene=mt_deck.shift();mt_current={scene,q:mt_pickQ(scene)};mt_round++;mt_locked=false;mt_render();}
function mt_esc(s){return String(s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function mt_ensureStyles(){if(document.getElementById('mt-style'))return;const s=document.createElement('style');s.id='mt-style';s.textContent=`
@keyframes mtShake{0%,100%{transform:translateX(0)}25%{transform:translateX(-7px)}50%{transform:translateX(7px)}75%{transform:translateX(-4px)}}
@keyframes mtGlow{0%,100%{box-shadow:none}50%{box-shadow:0 0 30px rgba(217,70,239,.26)}}
.mt-shake{animation:mtShake .3s ease}.mt-correct{animation:mtGlow .65s ease}
.mt-layout{display:grid;grid-template-columns:minmax(300px,410px) minmax(0,1fr);gap:14px;align-items:stretch}.mt-picwrap{position:relative;aspect-ratio:1/1;width:100%;overflow:hidden;border-radius:22px}.mt-pic{width:100%;height:100%;object-fit:cover;display:block}.mt-opts{display:grid;grid-template-columns:1fr;gap:9px;align-content:center}.mt-opt{min-height:58px;text-align:left}
@media(max-width:900px){.mt-layout{grid-template-columns:minmax(260px,350px) minmax(0,1fr);gap:10px}.mt-opt{min-height:54px}}@media(max-width:700px){.mt-layout{grid-template-columns:1fr}.mt-picwrap{max-width:430px;margin:0 auto}.mt-opts{grid-template-columns:1fr}.mt-opt{min-height:50px}}`;
document.head.appendChild(s);}
function startMallTalkGame(){mt_ensureStyles();mt_deck=[];mt_round=0;mt_cycle=0;mt_score=0;mt_streak=0;mt_best=0;mt_locked=false;mt_current=null;mt_tokens=0;Object.keys(mt_qState).forEach(k=>delete mt_qState[k]);mt_next();}
function mt_render(){const box=document.getElementById('game-play-container');if(!box||!mt_current)return;const [question,correct,rawOptions,type,explain]=mt_current.q;const options=mt_shuffle(rawOptions);box.innerHTML=`
<div class="rounded-[28px] border-2 border-fuchsia-200 bg-gradient-to-b from-fuchsia-50/70 via-pink-50/50 to-violet-50/55 p-2.5 md:p-3"><div class="flex items-center justify-between gap-2 mb-2"><div class="flex items-center gap-2 min-w-0"><span class="px-3 py-1.5 rounded-full bg-white/90 border-fuchsia-200 text-fuchsia-700 font-black text-xs md:text-sm shrink-0">💬 Lượt ${mt_round}</span><span class="px-2.5 py-1 rounded-full bg-fuchsia-100 text-fuchsia-700 font-black text-[10px] md:text-xs">${mt_esc(type)}</span></div><div class="flex gap-1.5 shrink-0"><span class="px-2.5 py-1.5 rounded-full bg-amber-50 border border-amber-200 text-amber-700 font-black text-xs md:text-sm">⭐ ${mt_score}</span><span class="px-2.5 py-1.5 rounded-full bg-rose-50 border border-rose-200 text-rose-600 font-black text-xs md:text-sm">🔥 x${mt_streak}</span><span class="px-2.5 py-1.5 rounded-full bg-fuchsia-50 text-fuchsia-700 border border-fuchsia-200 font-black text-xs md:text-sm">🌟 ${mt_tokens}</span></div></div>
<div data-minigame-question class="mb-2 px-3 py-2 rounded-2xl bg-white/90 border-fuchsia-200 text-center font-black text-slate-700 text-sm md:text-lg leading-snug">${mt_esc(question)}</div>
<div class="mt-layout"><div class="mt-picwrap"><img class="mt-pic" src="${mt_current.scene.image}" alt="Tranh trung tâm thương mại"></div><div class="mt-opts">${options.map((op,i)=>`<button class="mt-opt px-4 py-2.5 rounded-2xl border-2 ${['bg-white border-sky-200 hover:bg-sky-50','bg-white border-emerald-200 hover:bg-emerald-50','bg-white border-amber-200 hover:bg-amber-50','bg-white border-violet-200 hover:bg-violet-50'][i]} text-slate-700 font-extrabold text-sm md:text-[15px] leading-snug shadow-sm transition-all" data-answer="${mt_esc(op)}" onclick="mt_choose(this)">${mt_esc(op)}</button>`).join('')}<div id="mt-feedback" class="min-h-[34px] flex items-center justify-center text-center text-xs md:text-sm font-black text-fuchsia-700">🌟 Chọn lời nói rõ ràng, lịch sự và phù hợp để nhận “sao giao tiếp”!</div></div></div></div>`;
if(typeof setMiniGameQuestionAudio==='function')setMiniGameQuestionAudio(question,0.92);if(typeof mtSpeakSafe==='function')setTimeout(()=>mtSpeakSafe(question,0.92),140);}
function mt_choose(btn){if(mt_locked||!mt_current)return;const answer=btn.dataset.answer;const correct=mt_current.q[1];const explain=mt_current.q[4]||'';if(answer===correct){mt_locked=true;mt_score+=12+Math.min(mt_streak,5)*2;mt_streak++;mt_best=Math.max(mt_best,mt_streak);mt_tokens++;btn.classList.add('bg-emerald-100','border-emerald-400','text-emerald-800','mt-correct');const fb=document.getElementById('mt-feedback');if(fb)fb.innerHTML=`🌟 Lời nói rất đẹp! <span class="ml-1">${mt_esc(explain)}</span>`;if(typeof playAudio==='function')playAudio('correct');if(typeof confetti==='function')confetti({particleCount:55,spread:70,origin:{y:.72}});if(typeof mtSpeakSafe==='function')mtSpeakSafe('Chính xác! Bé giao tiếp thật lịch sự.',1.0);setTimeout(mt_next,1500);}else{mt_streak=0;btn.classList.add('mt-shake','border-rose-400','bg-rose-50');setTimeout(()=>btn.classList.remove('mt-shake','border-rose-400','bg-rose-50'),360);const fb=document.getElementById('mt-feedback');if(fb)fb.textContent='💭 Câu này chưa phù hợp nhất. Bé thử chọn lời vừa rõ ý vừa lễ phép nhé!';if(typeof playAudio==='function')playAudio('wrong');}}

window.startMallTalkGame=startMallTalkGame;window.mt_choose=mt_choose;
